CREATE OR REPLACE FUNCTION public.create_luna_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,name,handle) VALUES (NEW.id, 'Miembro Luna', 'luna' || left(replace(NEW.id::text,'-',''),12)) ON CONFLICT (id) DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER luna_auth_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_luna_profile();
CREATE OR REPLACE FUNCTION public.complete_luna_registration(p_name text, p_full_name text, p_birth_date date, p_zodiac text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; UPDATE public.profiles SET name = p_name WHERE id = auth.uid(); INSERT INTO public.profile_private(user_id,full_name,birth_date,zodiac,simulation_completed,simulation_completed_at) VALUES(auth.uid(),p_full_name,p_birth_date,p_zodiac,true,now()) ON CONFLICT(user_id) DO UPDATE SET full_name=excluded.full_name,birth_date=excluded.birth_date,zodiac=excluded.zodiac,simulation_completed=true,simulation_completed_at=now(); END; $$;
REVOKE ALL ON FUNCTION public.complete_luna_registration(text,text,date,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.complete_luna_registration(text,text,date,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.create_luna_group(p_name text, p_description text, p_category text) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE gid uuid; BEGIN INSERT INTO public.groups(name,description,category,creator_id) VALUES(p_name,p_description,p_category,auth.uid()) RETURNING id INTO gid; INSERT INTO public.group_members(group_id,user_id) VALUES(gid,auth.uid()); RETURN gid; END; $$;
REVOKE ALL ON FUNCTION public.create_luna_group(text,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_luna_group(text,text,text) TO authenticated;